cat > /workspace/src/image.hpp <<'EOF'
#ifndef SCAMP_IMAGE_HPP
#define SCAMP_IMAGE_HPP

#include "scamptrie_base.h"
#include <array>
#include <bitset>
#include <cstdint>
#include <string>
#include <utility>
#include <vector>

struct ImageLoc { int stage = -1; uint32_t cell = 0; };
struct ImageFront { uint64_t key; ImageLoc loc; };
struct ImageData {
    ImageLoc root;
    std::vector<ImageFront> front16, front64;
    std::array<uint32_t, RAM_NUM> cells{};
    std::array<std::vector<std::bitset<256>>, RAM_NUM> banks;
    std::vector<uint64_t> bitmaps;
    std::vector<uint32_t> nexthops;
};

// Reserved BMP field value denoting "no matching prefix".
static constexpr uint64_t IMAGE_BMP_NULL = 4194303ull;

class Fib;

// Decoded node of a loaded image (also the traversal state used by lookups).
struct ImageNode {
    int type = 0;
    int origin = 0;      // 0, 16 or 64
    int depth = 0;       // global depth of this node
    int stage = 0;
    uint64_t bmp = IMAGE_BMP_NULL;
    uint64_t pattern = 0;      // NI bitmap pattern (TYPE1/2/3)
    uint32_t ni_base = 0;
    int ni_count = 0;
    uint64_t bulk_bitmap = 0;
    uint32_t bulk_base = 0;
    int bulk_stage = 0;
    struct Child { uint8_t key; int stage; uint32_t cell; };
    std::vector<Child> children;      // explicit (non bulk) children
    struct Pfx { uint8_t l; uint32_t hop; uint64_t hi, lo; };
    std::vector<Pfx> inlines;         // TYPE4/5 inline prefixes
    int owned = 0;
};

// A validated, self contained packed image.  Lookup never touches a live trie.
class MemoryImage {
public:
    MemoryImage() = default;
    // Validate the complete self-contained image before replacing loaded state.
    bool load(const ImageData& proposed);
    nexthop_t lookup(ip6_t ip) const;
    bool empty() const { return nodes_.empty() && root_idx_ < 0 && front16_.empty() && front64_.empty(); }

private:
    nexthop_t walk(int idx, uint64_t cursor) const;
    int find_front(const std::vector<std::pair<uint32_t,int>>& v, uint64_t key) const;

    ImageData data_;
    std::vector<ImageNode> nodes_;
    std::vector<std::vector<int> > slots_;   // [stage][cell] -> node index
    int root_idx_ = -1;
    std::vector<std::pair<uint32_t,int> > front16_, front64_;
};

// Build a compact, spec conformant image of the given live FIB.
ImageData build_image(const Fib& fib);

std::string image_word_hex(const std::bitset<256>& bits);
std::bitset<256> image_word_from_hex(const std::string& text);
#endif
EOF
echo ok
